// Adding the dev container feature to a project from the app. Run with: npm test
'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('fs');
const os = require('os');
const path = require('path');
const setup = require('../devcontainer-setup');

const strip = text => JSON.parse(text.replace(/\/\/.*$/gm, '').replace(/\/\*[\s\S]*?\*\//g, '').replace(/,(\s*[}\]])/g, '$1'));

test('adds to an existing features block, keeping comments and tabs', () => {
  const before = [
    '// Generated by VS Code',
    '{',
    '\t"name": "Node", // the name',
    '\t"features": {',
    '\t\t"ghcr.io/devcontainers/features/git:1": {} // keep me',
    '\t},',
    '\t/* block */ "remoteUser": "node"',
    '}',
    ''
  ].join('\n');
  const { text, changed } = setup.addFeatureToConfigText(before);
  assert.ok(changed);
  assert.equal(text, [
    '// Generated by VS Code',
    '{',
    '\t"name": "Node", // the name',
    '\t"features": {',
    '\t\t"ghcr.io/devcontainers/features/git:1": {}, // keep me',
    '\t\t"./claude-code-stay-awake": {}',
    '\t},',
    '\t/* block */ "remoteUser": "node"',
    '}',
    ''
  ].join('\n'));
  assert.deepEqual(Object.keys(strip(text).features), ['ghcr.io/devcontainers/features/git:1', './claude-code-stay-awake']);
});

test('creates the features block when there is none (CRLF, spaces)', () => {
  const before = '{\r\n  "image": "mcr.microsoft.com/devcontainers/base:ubuntu"\r\n}\r\n';
  const { text } = setup.addFeatureToConfigText(before);
  assert.equal(text, '{\r\n  "image": "mcr.microsoft.com/devcontainers/base:ubuntu",\r\n  "features": {\r\n    "./claude-code-stay-awake": {}\r\n  }\r\n}\r\n');
});

test('handles trailing commas, empty and single-line features', () => {
  const trailing = setup.addFeatureToConfigText('{\n  "features": {\n    "a": {},\n  },\n}\n').text;
  assert.deepEqual(Object.keys(strip(trailing).features), ['a', './claude-code-stay-awake']);
  assert.ok(!trailing.includes(',,'));

  assert.equal(setup.addFeatureToConfigText('{\n  "features": {}\n}').text,
    '{\n  "features": {\n    "./claude-code-stay-awake": {}\n  }\n}');
  assert.equal(setup.addFeatureToConfigText('{ "features": { "a": {} } }').text,
    '{ "features": { "a": {}, "./claude-code-stay-awake": {} } }');
});

test('non-default bridge port becomes a feature option', () => {
  const { text } = setup.addFeatureToConfigText('{\n  "features": {}\n}', { bridgePort: 50000 });
  assert.deepEqual(strip(text).features['./claude-code-stay-awake'], { bridgePort: '50000' });
});

test('leaves a config alone when the feature is already there', () => {
  for (const key of ['./claude-code-stay-awake', 'ghcr.io/stanley-projects/insomnia/claude-code-stay-awake:1']) {
    const before = `{ "features": { "${key}": {} } }`;
    const r = setup.addFeatureToConfigText(before);
    assert.equal(r.changed, false);
    assert.equal(r.text, before);
    assert.equal(r.existingKey, key);
  }
});

test('refuses to edit what it cannot parse', () => {
  assert.throws(() => setup.addFeatureToConfigText('{ "features": { '));
  assert.throws(() => setup.addFeatureToConfigText('{ "features": [] }'));
});

test('remove undoes add', () => {
  // Byte for byte when the features block already had entries.
  for (const before of [
    '{\n\t"name": "x", // c\n\t"features": {\n\t\t"a": {} // keep me\n\t}\n}\n',
    '{\r\n  "features": {\r\n    "a": {},\r\n    "b": {}\r\n  }\r\n}\r\n',
    '{ "features": { "a": {} } }'
  ]) {
    assert.equal(setup.removeFeatureFromConfigText(setup.addFeatureToConfigText(before).text).text, before);
  }
  // Otherwise an empty features block is left behind, which is harmless.
  const removed = setup.removeFeatureFromConfigText(setup.addFeatureToConfigText('{\r\n  "image": "i"\r\n}\r\n').text).text;
  assert.deepEqual(strip(removed), { image: 'i', features: {} });

  // An entry the user placed in the middle.
  const mid = '{\n  "features": {\n    "a": {},\n    "./claude-code-stay-awake": {},\n    "b": {}\n  }\n}';
  assert.equal(setup.removeFeatureFromConfigText(mid).text, '{\n  "features": {\n    "a": {},\n    "b": {}\n  }\n}');
});

function makeProject(t, files) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'insomnia-dc-'));
  t.after(() => fs.rmSync(dir, { recursive: true, force: true }));
  for (const [rel, content] of Object.entries(files)) {
    fs.mkdirSync(path.dirname(path.join(dir, rel)), { recursive: true });
    fs.writeFileSync(path.join(dir, rel), content);
  }
  return dir;
}

test('finds configs from the project root, .devcontainer, or a named config', t => {
  const dir = makeProject(t, {
    '.devcontainer/devcontainer.json': '{}',
    '.devcontainer/python/devcontainer.json': '{}',
    '.devcontainer/claude-code-stay-awake/devcontainer-feature.json': '{}'
  });
  const all = [path.join(dir, '.devcontainer', 'devcontainer.json'), path.join(dir, '.devcontainer', 'python', 'devcontainer.json')];
  assert.deepEqual(setup.findDevcontainerConfigs(dir).configs, all);
  assert.deepEqual(setup.findDevcontainerConfigs(path.join(dir, '.devcontainer')).configs, all);
  assert.deepEqual(setup.findDevcontainerConfigs(path.join(dir, '.devcontainer', 'python')).configs, [all[1]]);

  const rootOnly = makeProject(t, { '.devcontainer.json': '{}' });
  assert.deepEqual(setup.findDevcontainerConfigs(rootOnly), { configs: [], rootLevel: path.join(rootOnly, '.devcontainer.json') });
});

test('install copies the feature with LF endings, uninstall removes it', t => {
  const dir = makeProject(t, {
    '.devcontainer/devcontainer.json': '{\n  "image": "x"\n}\n',
    '.devcontainer/init-firewall.sh': 'iptables -A OUTPUT -j REJECT\n'
  });
  const config = path.join(dir, '.devcontainer', 'devcontainer.json');
  assert.equal(setup.getFeatureStatus(config), 'missing');

  const r = setup.installFeature(config);
  assert.ok(r.configChanged && r.filesWritten);
  assert.equal(r.warnings.length, 1, 'warns about the firewall');
  const featureDir = path.join(dir, '.devcontainer', 'claude-code-stay-awake');
  for (const f of ['install.sh', 'claude-hook.sh', 'devcontainer-feature.json', 'insomnia-hooks.json', '.gitattributes']) {
    assert.ok(!fs.readFileSync(path.join(featureDir, f), 'utf8').includes('\r'), f);
  }
  assert.equal(setup.getFeatureStatus(config), 'ok');

  // Running it again only refreshes the files.
  fs.writeFileSync(path.join(featureDir, 'install.sh'), 'old');
  assert.equal(setup.getFeatureStatus(config), 'outdated');
  assert.equal(setup.installFeature(config).configChanged, false);
  assert.equal(setup.getFeatureStatus(config), 'ok');

  const u = setup.uninstallFeature(config);
  assert.ok(u.configChanged && u.filesRemoved);
  assert.ok(!fs.existsSync(featureDir));
  assert.deepEqual(strip(fs.readFileSync(config, 'utf8')), { image: 'x', features: {} });
});

test('never overwrites a folder that is not ours, and skips the copy for the published feature', t => {
  const dir = makeProject(t, {
    '.devcontainer/devcontainer.json': '{}',
    '.devcontainer/claude-code-stay-awake/notes.txt': 'mine'
  });
  const config = path.join(dir, '.devcontainer', 'devcontainer.json');
  assert.throws(() => setup.installFeature(config), /not Insomnia's feature/);
  assert.equal(fs.readFileSync(config, 'utf8'), '{}');
  setup.uninstallFeature(config);
  assert.ok(fs.existsSync(path.join(dir, '.devcontainer', 'claude-code-stay-awake', 'notes.txt')));

  const pub = makeProject(t, { '.devcontainer/devcontainer.json': '{ "features": { "ghcr.io/stanley-projects/insomnia/claude-code-stay-awake:1": {} } }' });
  const pubConfig = path.join(pub, '.devcontainer', 'devcontainer.json');
  const r = setup.installFeature(pubConfig);
  assert.equal(r.filesWritten, false);
  assert.ok(r.publishedKey);
  assert.equal(setup.getFeatureStatus(pubConfig), 'published');
});
